from django.db import migrations, models

def unificar_registros(modelo, nome_campo='nome'):
    registros_repetidos = modelo.objects.values(nome_campo).annotate(
        contagem=models.Count(nome_campo)
    ).filter(
        contagem__gt=1
    ).values_list(nome_campo, flat=True)

    anterior = ''
    for registro in modelo.objects.filter(**{f'{nome_campo}__in': registros_repetidos}).order_by(nome_campo):
        campo = getattr(registro, nome_campo)
        if campo == anterior:  # so altera a partir do segundo registro com o mesmo nome    
            print(f'Alterando {modelo.__name__} {campo} #{registro.id}')
            setattr(registro, nome_campo, f'{campo} #{registro.id}')
            registro.save()
        else:
            anterior = campo

